INSERT INTO document_revisions (id,source_document_id,content_hash,source_commit_sha,byte_size,modified_at,is_current) VALUES ($1,$2,$3,$4,$5,to_timestamp($6::double precision / 1000000000),true) ON CONFLICT (source_document_id,content_hash) DO UPDATE SET source_commit_sha=EXCLUDED.source_commit_sha,byte_size=EXCLUDED.byte_size,modified_at=EXCLUDED.modified_at,is_current=true RETURNING id
